"""Generate browser lookups from the maintained guide page-map JSON files."""
from pathlib import Path
import json
root=Path(__file__).resolve().parents[2]
p1=json.loads((root/'revision/h446/guides/paper-1-page-map.json').read_text())
p2=json.loads((root/'revision/h446/guides/paper-2-page-map.json').read_text())
script="""'use strict';
// Generated by tools/revision/build_guide_links.py. Edit the source page-map JSON.
// Quiz banks retain stable page keys from the pre-reorder editions.
(function(){
 const pages=MAP1;
 const pages2=MAP2;
 const edition=EDITION1;
 const paper2Edition=EDITION2;
 function lookup(pages,key,paper){const page=pages[String(key)];if(!Number.isInteger(page))throw new RangeError('Unknown Paper '+paper+' guide key: '+key);return page;}
 function pageNumber(key){return lookup(pages,key,1);}
 function paper2PageNumber(key){return lookup(pages2,key,2);}
 function paper1(key){return '/revision/h446/guides/H446_Paper_1_CORRECTED_DRAFT_2026-10-21.pdf?v='+edition+'#page='+pageNumber(key);}
 function paper2(key){return '/revision/h446/guides/H446_Paper_2_REVIEW_READY_2026-10-21.pdf?v='+paper2Edition+'#page='+paper2PageNumber(key);}
 window.RHSC_GUIDE_LINKS=Object.freeze({edition,pageNumber,paper1,paper2Edition,paper2PageNumber,paper2});
})();
"""
for k,v in [('MAP1',p1['page_keys']),('MAP2',p2['page_keys']),('EDITION1',p1['edition']),('EDITION2',p2['edition'])]:script=script.replace(k,json.dumps(v,separators=(',',':')))
(root/'revision/h446/guide-links.js').write_text(script)
